import { createApp } from "vue";
import { ConvexProvider, ConvexVueClient } from "convex-vue";
import "./style.css";
import App from "./App.vue";

const convex = new ConvexVueClient(import.meta.env.VITE_CONVEX_URL as string);

createApp(App).use(ConvexProvider, { client: convex }).mount("#app");

:root {
  font-family: "Inter", system-ui, sans-serif;
  color: #111827;
  background-color: #f3f4f6;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
}

#app {
  min-height: 100vh;
}

.app {
  display: flex;
  justify-content: center;
  padding: 48px 20px;
}

.card {
  width: 100%;
  max-width: 640px;
  background: #ffffff;
  border-radius: 16px;
  padding: 32px;
  box-shadow: 0 20px 40px rgba(15, 23, 42, 0.1);
}

.header h1 {
  margin: 0 0 8px;
  font-size: 32px;
}

.header p {
  margin: 0 0 24px;
  color: #6b7280;
}

.input-row {
  display: flex;
  gap: 12px;
  margin-bottom: 24px;
}

#new-task-input {
  flex: 1;
  padding: 12px 14px;
  border-radius: 10px;
  border: 1px solid #d1d5db;
  font-size: 16px;
}

#add-task-btn {
  padding: 12px 18px;
  border-radius: 10px;
  border: none;
  background: #2563eb;
  color: #fff;
  font-size: 16px;
  cursor: pointer;
}

#add-task-btn:hover {
  background: #1d4ed8;
}

.task-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.task-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 14px 16px;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
}

.task-item span {
  font-size: 16px;
}

.task-item span.completed {
  text-decoration: line-through;
  color: #9ca3af;
}

.actions {
  display: flex;
  gap: 8px;
}

.toggle-btn,
.delete-btn {
  padding: 8px 12px;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  font-size: 14px;
}

.toggle-btn {
  background: #10b981;
  color: #fff;
}

.toggle-btn:hover {
  background: #059669;
}

.delete-btn {
  background: #ef4444;
  color: #fff;
}

.delete-btn:hover {
  background: #dc2626;
}

